import { getNotificationPreference } from "@/lib/data";
import { toggleNotifications } from "./actions";
import { SubmitButton } from "./submit-button";

export default async function Home() {
  const notificationsEnabled = await getNotificationPreference("user_1");

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Notifications are currently{" "}
        <strong>{notificationsEnabled ? "ON" : "OFF"}</strong>.
      </p>
      <form action={toggleNotifications}>
        <SubmitButton />
      </form>
    </main>
  );
}

import type { ReactNode } from "react";

export default function RootLayout({ children }: { children: ReactNode }) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  );
}

"use client";

import { useFormStatus } from "react-dom";

export function SubmitButton() {
  const { pending } = useFormStatus();
  return (
    <button type="submit" disabled={pending} aria-disabled={pending}>
      {pending ? "Saving..." : "Toggle notifications"}
    </button>
  );
}

"use server";

import { revalidatePath } from "next/cache";
import {
  getNotificationPreference,
  setNotificationPreference,
} from "@/lib/data";

export async function toggleNotifications() {
  const userId = "user_1";
  const current = await getNotificationPreference(userId);
  await setNotificationPreference(userId, !current);

  revalidatePath("/");
}

const preferences = new Map<string, boolean>([["user_1", true]]);

export async function getNotificationPreference(
  userId: string
): Promise<boolean> {
  return preferences.get(userId) ?? false;
}

export async function setNotificationPreference(
  userId: string,
  value: boolean
): Promise<void> {
  preferences.set(userId, value);
}

